import React, { useEffect, useState } from 'react'
import StoresTable from './StoresTable'

import useApi from '../../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import EntitySubStoreFormModal from './EntitySubStoreFormModal';
import frequenciesApi from '../../../api/drugs/frequenciesApi';
import { Loading } from '../../../components';
import logisticsApi from '../../../api/logistics/logisticsApi';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function EntitySubStoresList() {
    const [openFormModal, setopenFormModal] = useState(false)

    const navigate = useNavigate()
    const [entitySubStore, setEntitySubStore] = useState()
    const [entitySubStores, setEntitySubStores] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const entitySubStoresActionsApi = useApi(logisticsApi.logisticsAdminAction)

    const getEntitySubStores = async () => {
        await entitySubStoresActionsApi.request({
            "action": "GetEntitySubStores"

        })
    }


    useEffect(() => {
        getEntitySubStores()
    }, [])


    const handleEditAction = (item) => {

        setopenFormModal(true)
        setEntitySubStore(item)
        setmodalTitle(`Edit ${item.tittle}`)
        setUpdated(false)

    }

    const handleAddAction = () => {
        setopenFormModal(true)
        setmodalTitle("Add new body system")
        setEntitySubStore(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/systems/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/systems/delete/${item.id}`)
    }


    useEffect(() => {

        if (entitySubStoresActionsApi.data && entitySubStoresActionsApi.data.length) {

            setEntitySubStores(entitySubStoresActionsApi.data)
        }
    }, [entitySubStoresActionsApi.data])

    useEffect(() => {
        getEntitySubStores()
    }, [updated])


    //Filtering data
    useEffect(() => {
        setdata(entitySubStores)
    }, [entitySubStores])


    const handleFilter = (e) => {
        const search_param = e
        if (entitySubStores && entitySubStores.length > 0 && search_param && search_param !== '') {
            setdata(entitySubStores.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(entitySubStores);
        }

    };

    return entitySubStoresActionsApi.loading ? <Loading loading={frequenciesApi.loading} /> : (
        <div className='mt-16 md:mt-2'>
            {openFormModal && <EntitySubStoreFormModal openFormModal={openFormModal} setopenFormModal={setopenFormModal} entitySubStore={entitySubStore} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <StoresTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default EntitySubStoresList