import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomTextArea,
} from "../../../components";
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "dayjs/locale/en-gb";
import { useDispatch } from "react-redux";
import { getLoggedInUser } from "../../../helpers/authUtils";

import useApi from "../../../hooks/useApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import frequenciesApi from "../../../api/drugs/frequenciesApi";
import { Modal } from "antd";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";
import routesApi from "../../../api/drugs/routesApi";
import departmentsApi from "../../../api/departmentsApi";
import logisticsApi from "../../../api/logistics/logisticsApi";

export default function EntitySubStoreFormModal({
  openFormModal,
  setopenFormModal, entitySubStore,
  setUpdated,
  updated
}) {
  const dispatch = useDispatch();
  const [user, setUser] = useState();
  const [errors, setErrors] = useState();
  const { currentColor, loggedInUser } = useStateContext();

  //Retrieve entity stores
  const [entityStores, setEntityStores] = useState([]);
  const getEntityStoresApi = useApi(logisticsApi.logisticsAdminAction);
  const getEntityStores = async () => {
    await getEntityStoresApi.request({
      action: "GetEntityStores",
    });
  };
  useEffect(() => {
    if (getEntityStoresApi.data && getEntityStoresApi.data.length) {
      setEntityStores(
        getEntityStoresApi.data.map((i) => ({ label: `${i.title}`, value: i.id }))
      );
    }

    console.log("getEntityStoresApi.data", getEntityStoresApi.data);
  }, [getEntityStoresApi.data]);


  useEffect(() => {

    getEntityStores();


  }, []);




  const entitySubStoreActionApi = useApi(logisticsApi.logisticsAdminAction);
  const handleEntitySubStoreAction = async (data) => {
    await entitySubStoreActionApi.request(data);
  };

  useEffect(() => {
    if (entitySubStoreActionApi.data) {
      if (entitySubStoreActionApi.data.entity_sub_store) {
        toast.success(entitySubStoreActionApi.data.response_message);
        setUpdated(true)
        setopenFormModal(false)
      } else {
        toast.error(entitySubStoreActionApi.data.response_message);
      }
    }
    console.log("entitySubStoreActionApi.data", entitySubStoreActionApi.data)
  }, [entitySubStoreActionApi.data]);



  const formik = useFormik({
    initialValues: {
      title: entitySubStore ? entitySubStore.title : "",
      description: entitySubStore ? entitySubStore.description : "",
      entity_store: entitySubStore?{label:entitySubStore.title,value:entitySubStore.id}:""

    },

    validationSchema: Yup.object({
      title: Yup.string().required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action
      let data = null;
      console.log("VALZ", values)

      if (entitySubStore) {
        data = {
          action: "UpdateEntitySubStore",
          entity_sub_store: entitySubStore.id,
          title: values.title,
          description: values.description,
        };
      } else {
        data = {
          action: "CreateEntitySubStore",
          entity_store:values.entity_store.id,
          title: values.title,
          description: values.description,

        };
      }

      handleEntitySubStoreAction(data);

      // resetForm();
    },
  });

  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setopenFormModal(false);
  };
  const handleCancel = () => {
    setopenFormModal(false);
  };

  return (
    <div className=" max-w-fit min-w-fit">
      <ToastContainer theme="colored" position="bottom-center" />
      <Modal
        width={600}
        className="w-full text-center capitalize"
        title={
          entitySubStore
            ? "EDIT " + entitySubStore.title
            : "ADD NEW DEPARTMENT"
        }
        open={openFormModal}
        onOk={handleOk}
        onCancel={handleCancel}
        closeIcon={true}
        closable={false}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
            className="w-full"
          >
            <CustomInput
              id="title"
              name="title"
              required={true}
              onChange={formik.handleChange}
              placeholder="Enter title"
              label="Enter title"
              size="large"
              type="text"
              value={formik.values.title}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.entity_store}
            error={formik.errors.entity_store}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="entity_store"
              id="entity_store"
              label="Select entity_store"
              size="large"
              onChange={(value) => formik.setFieldValue("entity_store", value)}
              value={formik.values.entity_store}
              placeholder="Select entity store"
              options={entityStores}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
            className="w-full"
          >
            <CustomTextArea
              rows={2}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Any description"
              label="Any description"
              size="large"
              type="text"
              value={formik.values.description}
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button
              style={{ background: currentColor }}
              className="w-36 rounded-md"
              color="primary"
              type="submit"
            >
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
